function ReasoningPart({
  text,
  status,
  show = true,
}: {
  text: string;
  status?: { type: string };
  show?: boolean;
}) {
  const [open, setOpen] = useState(() => status?.type === "running");
  const userToggledRef = useRef(false);

  useEffect(() => {
    if (status?.type === "running") {
      userToggledRef.current = false;
      setOpen(true);
      return;
    }
    if (!userToggledRef.current) setOpen(false);
  }, [status?.type]);

  if (!show) return null;
  if (!text.trim()) return null;
  return (
    <details
      open={open}
      onToggle={(event) => {
        userToggledRef.current = true;
        setOpen(event.currentTarget.open);
      }}
      className={css({
        marginBottom: "0.75rem",
        borderRadius: "0.375rem",
        border: "1px solid var(--border)",
        backgroundColor: "color-mix(in srgb, var(--muted) 40%, transparent)",
        paddingInline: "0.75rem",
        paddingBlock: "0.5rem",
        fontSize: "0.75rem",
        color: "var(--muted-foreground)",
      })}
    >
      <summary
        className={css({
          display: "flex",
          cursor: "pointer",
          listStyle: "none",
          alignItems: "center",
          justifyContent: "space-between",
          gap: "0.5rem",
          fontWeight: 500,
        })}
      >
        <span className={css({ display: "flex", alignItems: "center", gap: "0.375rem" })}>
          <ChevronRight
            size={13}
            aria-hidden="true"
            className={css({
              flexShrink: 0,
              transitionProperty: "transform",
              transitionDuration: "150ms",
              transform: open ? "rotate(90deg)" : "rotate(0deg)",
            })}
          />
          <span>Reasoning</span>
        </span>
        <CopyButton text={text} label="Copy" />
      </summary>
      <div
        className={cx(
          "keating-reasoning-markdown",
          css({
            marginTop: "0.5rem",
            overflowWrap: "break-word",
          }),
        )}
      >
        <ReactMarkdown
          remarkPlugins={[remarkGfm, remarkMath]}
          rehypePlugins={[rehypeKatex]}
          components={MARKDOWN_COMPONENTS}
        >
          {text}
        </ReactMarkdown>
      </div>
    </details>
  );
}

function formatToolResult(result: unknown) {
  if (result === undefined) return "";
  if (typeof result === "string") return result;
  if (Array.isArray(result)) {
    const text = result
      .map((part) => {
        if (part?.type === "text" && typeof part.text === "string")
          return part.text;
        return "";
      })
      .filter(Boolean)
      .join("\n");
    if (text) return text;
